        leftVertices.add(leftVertex);
    }

    // Create a list of vertices for the right side of the bipartite graph
    List<V> rightVertices = new ArrayList<>();
    for (int i = resultMap.size(); i < 2 * resultMap.size(); i++) {
        V rightVertex = new Vertex<>(i, i);
        rightVertices.add(rightVertex);
    }

    // Add all edges between the left and right sides of the bipartite graph
    for (int i = 0; i < leftVertices.size(); i++) {
        for (int j = 0; j < rightVertices.size(); j++) {
            target.addEdge(Left(leftVertices.get(i), rightVertices.get(j)));
