public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Initialize edges and vertices
    List<E> edges = new ArrayList<>();
    List<V> vertices = new ArrayList<>();

    // Determine the number of vertices in each partition
    int n1 = resultMap.size();
    int n2 = (int) Math.ceil(Math.sqrt(target.getNumberOfVertices() / 2));

    // Add vertices to the graph
    for (int i = 0; i < n1 + n2; i++) {
        vertices.add(i);
    }

    // Add edges to the graph
    for (int i = 0; i < n1; i++) {
        for (int j = 0; j < n2; j++) {
            edges.add(new Edge<>(vertices.get(i), vertices.get(n1 + j)));
        }
    }

    // Add the edges to the graph
    target.addEdges(edges);
