}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Initialize a circulator to the start node
    OuterFaceCirculator cir = new OuterFaceCirculator(start, dir);

    // Iterate through the nodes on the outer face until we find a node that satisfies the predicate
    while (cir.hasNext() && !predicate.test(cir.current)) {
        cir.next();
    }

    // If we didn't find a node that satisfies the predicate, return a circulator to the stop node
    if (!predicate.test(cir.current)) {
        cir = new OuterFaceCirculator(stop, dir);
    }

    return cir;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Create a circulator that starts at the given start node
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);

    // Loop until we find a node that satisfies the predicate or reach the stop node
    while (circulator.hasNext() && !predicate.test(circulator.getNode())) {
        circulator.moveNext();
    }

    // Return the circulator to the node that satisfies the predicate or to the stop node
    return circulator;
}

