private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Find the bucket with label minLabel and the bucket with label 0
    Set<Integer> fromBucket = bucketsByLabel.get(minLabel);
    Set<Integer> toBucket = bucketsByLabel.get(0);

    // Move all vertices from the bucket with label minLabel to the bucket with label 0
    toBucket.addAll(fromBucket);

    // Update the labeling of the vertices
    for (int vertex : fromBucket) {
        labels.set(vertex, 0);
    }

    // Clear the bucket with label minLabel
    fromBucket.clear();
}

