public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the graph is null or empty
    if (graph == null || graph.isEmpty()) {
        return false;
    }

    // Check if the vertex set is null or empty
    if (vertices == null || vertices.isEmpty()) {
        return false;
    }

    // Create a new set to store the neighbors of each vertex
    Set<V> neighbors = new HashSet<>();

    // Iterate over the vertices in the set
    for (V vertex : vertices) {
        // Add the vertex to the neighbors set
        neighbors.add(vertex);

        // Iterate over the neighbors of the vertex
        for (V neighbor : graph.getNeighbors(vertex)) {
            // Check if the neighbor is a valid vertex
            if (vertices.contains(neighbor)) {
                // Add the neighbor to the neighbors set
                neighbors.add(neighbor);
            }
        }
    }

    // Check if the set of neighbors is equal to the set of vertices
    return vertices.size() == neighbors.size();
}

