        if (component.equals(".")) {
            // If the component is ".", remove the last element from the path components array
            pathComponents = pathComponents.substring(0, pathComponents.length - 1);
        } else if (component.equals("..")) {
            // If the component is "..", remove the last two elements from the path components array
            pathComponents = pathComponents.substring(0, pathComponents.length - 2);
