public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (!line.isEmpty() && line.startsWith("CreateThreadSnapshot")) {
                String[] parts = line.split(",");
                String threadName = parts[1];
                long timestamp = Long.parseLong(parts[2]);
                if (timeRanges.stream().anyMatch(timeRange -> timeRange.contains(timestamp))) {
                    threadSnapshots.add(new ThreadSnapshot(threadName, timestamp));
                }
            }
        }
    }
    return threadSnapshots;
}

public List<ThreadSnapshot> parse(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
		List<ThreadSnapshot> snapshots = new ArrayList<ThreadSnapshot>();
		BufferedReader reader = null;
		try {
			reader = new BufferedReader(new FileReader(file));
			String line = null;
			while ((line = reader.readLine()) != null) {
				if (line.isEmpty()) {
					continue;
				}

				ThreadSnapshot snapshot = ThreadSnapshot.parse(line);
				if (snapshot == null) {
					continue;
				}

				long timestamp = snapshot.getTimestamp();
				if (timestamp == -1L) {
					timestamp = Long.parseLong(snapshot.getId().substring(0, snapshot.getId().indexOf('=')));
				}

				if (isInTimeRange(timestamp, timeRanges)) {
					snapshots.add(snapshot);
				}
			}
		} finally {
			if (reader != null) {
				reader.close();
			}
		}

		return snapshots;
	}

	private boolean isInTimeRange(long timestamp, List<ProfileAnalyzeTimeRange> timeRanges) {
		for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
			if (timestamp >= timeRange.getStart() && timestamp <= timeRange.getEnd()) {
				return true;
			}
		}
		return false;
	}
}

